function setLanguage(lang) {
    localStorage.setItem('preferredLanguage', lang);
    document.documentElement.lang = lang;
    
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (translations[lang][key]) {
            if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') {
                element.placeholder = translations[lang][key];
            } else {
                element.innerHTML = translations[lang][key];
            }
        }
    });

    // Update document title if applicable
    const titleKey = document.title.includes('|') ? null : 'seo-title'; // Avoid overwriting specific page titles unless intended
    // But we have page-specific seo-titles now.
    // Let's handle title specially if it has data-i18n
    const titleElem = document.querySelector('title[data-i18n]');
    if (titleElem) {
        const key = titleElem.getAttribute('data-i18n');
        if (translations[lang][key]) {
            document.title = translations[lang][key];
        }
    }

    // Update meta descriptions
    const metaDesc = document.querySelector('meta[name="description"][data-i18n]');
    if (metaDesc) {
        const key = metaDesc.getAttribute('data-i18n');
        if (translations[lang][key]) {
            metaDesc.setAttribute('content', translations[lang][key]);
        }
    }

    updateToggleUI(lang);
}

function updateToggleUI(lang) {
    const btn = document.getElementById('language-toggle');
    if (btn) {
        btn.innerHTML = lang === 'es' ? 'EN' : 'ES';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const savedLang = localStorage.getItem('preferredLanguage') || (navigator.language.startsWith('es') ? 'es' : 'en');
    setLanguage(savedLang);

    const toggleBtn = document.getElementById('language-toggle');
    if (toggleBtn) {
        toggleBtn.addEventListener('click', () => {
            const currentLang = document.documentElement.lang;
            const newLang = currentLang === 'es' ? 'en' : 'es';
            setLanguage(newLang);
        });
    }
});
